CREATE proc [dbo].[uspInsertOrderDetail] @OrderKey as int, @Item as nvarchar(100), @Qty as decimal(18,2),@Comments as nvarchar(MAX), @android_detail_id as int,@tax as decimal(18,2) as Declare @ShiftNo nvarchar(10); Declare @ShiftDate datetime; Declare @Category nvarchar(50); Declare @Price decimal(18,2); Declare @Amount decimal(18,2); Declare @OrderDetailId int; Declare @TiltId int; Declare @CounterId int; Declare @ItemId int;  select @TiltId = TiltId ,@CounterId = id from ShiftAmount where id = (select max(id) from ShiftAmount where IsActive = 1) Select @ShiftNo = z_report_number,@ShiftDate = opening_date from Shift_Opening where status = 1 Select @ItemId = id,@Category = category_name,@Price = sale_Price from ItemPos where item_name = @Item set @Amount = @Price * @Qty;  insert into Order_Detail (order_key,date,z_number,category_name,item_name,qty,price,tiltid,counterid,PriceBeforeDiscount,Comments,android_detail_id,tax,ItemId) values  (@OrderKey,@ShiftDate,@ShiftNo,@Category,@Item,@Qty,@Amount,@TiltId,@CounterId,@Amount,@Comments,@android_detail_id,@tax,@ItemId) select @OrderDetailId = scope_identity(); update order_detail set parent_id = @OrderDetailId where id = @OrderDetailId;  insert into OrderKot (OrderKey,ItemId,Qty,KotStatus,TiltId,OrderDetailId,kotFromtablet,Comments,ItemComment) values (@OrderKey,@ItemId,@Qty,1,@TiltId,@OrderDetailId,1,@Comments,@Comments)  select @OrderDetailId;